(()=>{const STAMP='2026-10-01T17:00:00+02:00';function run(){window.marketAgentUpdateMeta={contentUpdatedAt:STAMP,lastSuccessfulRunAt:STAMP,status:'partial',marketStatus:'US open',holdingsFallback:true};holdings.forEach(h=>{if(['CAT','JBL','LMT','MCD','AMZN','MEDP','NTAP','RNG'].includes(h.id)){h.lastCheckedAt=STAMP;h.changedSections=[];h.updateStatus='checked';delete h.updateTag}});const t=document.getElementById('content-state');if(t)t.textContent='Inhalte: 01.10.2026 · 17:00';const c=document.getElementById('content-state-chip');if(c){c.classList.remove('status-ok','status-error','status-closed');c.classList.add('status-partial');c.title='Holdings-Datei nicht erreichbar – letzter bestätigter Bestand verwendet.'}renderCards();renderDetail()}let i=setInterval(()=>{if(typeof renderCards==='function'){clearInterval(i);run()}},150)})();